import{_ as a,c as t,o as i,b0 as n}from"./chunks/framework.BWMBvyU7.js";const u=JSON.parse('{"title":"LV010-变量","description":null,"frontmatter":{"title":"LV010-变量","date":"2026-03-13T10:18:15.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/Language/shell/126d38c3f5f7226ae44859f7","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-03-13T10:18:15.550Z","fulluuid":"ae44859f7fef446580420c949dc69ef3","useduuid":"ae44859f7"}},"headers":[],"relativePath":"sdoc/Language/shell/126d38c3f5f7226ae44859f7.md","filePath":"sdoc/01-编程语言/10-Shell/LV010-变量.md","lastUpdated":1773672539000}'),e={name:"sdoc/Language/shell/126d38c3f5f7226ae44859f7.md"};function l(r,s,p,h,d,o){return i(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="lv010-变量" tabindex="-1">LV010-变量 <a class="header-anchor" href="#lv010-变量" aria-label="Permalink to &quot;LV010-变量&quot;">​</a></h1><h2 id="一、-shell-变量" tabindex="-1">一、 shell 变量 <a class="header-anchor" href="#一、-shell-变量" aria-label="Permalink to &quot;一、 shell 变量&quot;">​</a></h2><h3 id="_1-怎么定义" tabindex="-1">1. 怎么定义？ <a class="header-anchor" href="#_1-怎么定义" aria-label="Permalink to &quot;1. 怎么定义？&quot;">​</a></h3><p>shell 允许用户建立变量存储数据，但 <strong>不支持数据类型（整型、字符、浮点型）</strong>，将 <strong>任何赋给变量的值都解释为一串字符</strong>。变量定义格式如下（支持三种形式）：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Variable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">value</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 第一种</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Variable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;value&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 第二种</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Variable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;value&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 第三种</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>【<strong>注意</strong>】</p><p>（1）<strong>等号两边不允许有空格</strong>。</p><p>（2）命名只能使用 <strong>英文字母</strong>，<strong>数字</strong> 和 <strong>下划线</strong>，<strong>首个字符不能以数字开头</strong>，且中间不能有空格。</p><p>（3）不能使用标点符号，而且不能使用 bash 里的关键字（可用 help 命令查看保留关键字）。</p><p>（4）第二种与第三种的区别：</p><p>以单引号 &#39; &#39; 包围变量的值时，单引号里面是什么就输出什么，即使内容中有变量和命令（命令需要反引起来）也会把它们 <strong>原样输出</strong>。这种方式比较适合定义显示纯字符串的情况，即不希望解析变量、命令等的情况。</p><p>以双引号 &quot; &quot; 包围变量的值时，输出时会先 <strong>解析里面的变量和命令</strong>，而不是把双引号中的变量名和命令原样输出。这种方式比较适合字符串中附带有变量和命令并且想将其解析后再输出的变量定义。</p><h3 id="_2-怎么赋值" tabindex="-1">2. 怎么赋值？ <a class="header-anchor" href="#_2-怎么赋值" aria-label="Permalink to &quot;2. 怎么赋值？&quot;">​</a></h3><p>在 Bash shell 中，每一个变量的值都是字符串，<strong>无论给变量赋值时有没有使用引号，值都会以字符串的形式存储</strong>。这就意味着， Bash shell 在默认情况下不会区分变量类型，即使将整数和小数赋值给变量，它们也会被视为字符串。</p><ul><li>直接赋值</li></ul><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Variable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">value</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>用语句赋值</li></ul><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 赋值方式 1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Variable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> command</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 赋值方式 2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Variable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">command</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Variable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">command</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>【注意】用语句进行赋值时，语句一定要写在反引号符号里边，该符号为英文状态下 Esc 按键下边的哪个按键。或者也可以用 <code>$()</code> 的方式，这种方式看起来要更直观一些。</p><h3 id="_3-怎么使用" tabindex="-1">3. 怎么使用？ <a class="header-anchor" href="#_3-怎么使用" aria-label="Permalink to &quot;3. 怎么使用？&quot;">​</a></h3><p>使用一个定义过的变量，只要在变量名前面加美元符号（ $ ）即可。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\${Variable}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$Variable</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>【注意】</p><p>（1）变量名外面的 <strong>花括号是可选的</strong>，加不加都行，加花括号是为了帮助解释器识别变量的边界。推荐给所有变量加上花括号。</p><p>（2）定义变量和给变量赋值的时候都不需要加 $ ，使用的时候才需要加上。</p><h2 id="二、变量类型" tabindex="-1">二、变量类型 <a class="header-anchor" href="#二、变量类型" aria-label="Permalink to &quot;二、变量类型&quot;">​</a></h2><ul><li><p>局部变量：在脚本或命令中定义，仅在当前 shell 实例中有效，其他 shell 启动的程序不能访问局部变量。</p></li><li><p>环境变量：所有的程序，包括 shell 启动的程序，都能访问环境变量，有些程序需要环境变量来保证其正常运行。必要的时候 shell 脚本也可以定义环境变量。</p></li><li><p>shell 变量：shell 变量是由 shell 程序设置的特殊变量。 shell 变量中有一部分是环境变量，有一部分是局部变量，这些变量保证了 shell 的正常运行。</p></li></ul><h3 id="_1-bourne-shell-中的常用的四种变量" tabindex="-1">1. Bourne Shell 中的常用的四种变量 <a class="header-anchor" href="#_1-bourne-shell-中的常用的四种变量" aria-label="Permalink to &quot;1. Bourne Shell 中的常用的四种变量&quot;">​</a></h3><h4 id="_1-1-用户自定义变量" tabindex="-1">1.1 用户自定义变量 <a class="header-anchor" href="#_1-1-用户自定义变量" aria-label="Permalink to &quot;1.1 用户自定义变量&quot;">​</a></h4><p>就是用户自己定义的变量，在 shell 编程中，通常使用全大写，例如</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">COUNT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="_1-2-位置变量" tabindex="-1">1.2 位置变量 <a class="header-anchor" href="#_1-2-位置变量" aria-label="Permalink to &quot;1.2 位置变量&quot;">​</a></h4><p>在 Linux 的命令行中，当一条命令或脚本执行时，后面可以跟多个参数，可以使用位置参数变量来表示这些参数。</p><table><tbody><tr><td align="center" width="100px">$n </td><td align="left"> n 为数字，$0 代表命令本身，$ 1-$9 代表第 1-9 个参数，10 以上的参数需要用大括号{}包含， 例如\${10}，\${15}</td></tr><tr><td align="center" width="100px">$*</td><td align="left"> 代表命令行中所有的参数，把所有的参数看成一个整体 </td></tr><tr><td align="center" width="100px">$@</td><td align="left"> 代表命令行中所有的参数，不过 $@ 把每个参数区别对待 </td></tr><tr><td align="center" width="100px">$#</td><td align="left"> 代表命令行中所有参数的个数 </td></tr></tbody></table><p>【<strong>使用实例</strong>】</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hk@ubuntu-22-04:~/1sharedfiles/6temp/myubuntu$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./1.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1 2 3</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$#</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=3</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">$@</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1 2 3</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">$0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=./1.sh</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">$1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">$2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>【<strong>注意</strong>】</p><p>（1） $n 中， n 大于等于 10 时，一定要加上 {} 。</p><p>（2） $* 与 $@ ：</p><p>当 $* 和 $@ 不被双引号 &quot; &quot; 包含时，它们之间* <em>没有任何区别</em> <em>，都是将接收到的每个参数看做一份数据，彼此之间</em> <em>以空格来分隔</em>*，两者都以 &quot;$1&quot; &quot;$2&quot; … &quot;\\$n&quot; 的形式输出所有参数。</p><p>当 $* 和 $@ 被双引号 &quot; &quot; 包含时， &quot;$*&quot; 会将* <em>所有的参数从整体上看做一份数据</em> <em>，而不是把每个参数都看做一份数据，以 &quot;$1 $2 … $n&quot; 的形式输出所有参数； &quot;$@&quot; 仍然将</em> <em>每个参数都看作一份数据</em>*，彼此之间是独立的，以 &quot;$1&quot; &quot;$2&quot; … &quot;$n&quot; 的形式输出所有参数。</p><table><tbody><tr><td align="center" rowspan="2"> 变量 </td><td align="center" colspan="2"> 输出形式 </td></tr><tr><td align="center"> 被 &quot; &quot; 包含 </td><td align="center"> 不被 &quot; &quot; 包含 </td></tr><tr><td align="center">$*</td><td align="center"> &quot; $1 $ 2 … $n &quot;</td><td align="center"> &quot;$1&quot; &quot;$ 2&quot; … &quot;$n &quot;</td></tr><tr><td align="center">$@</td><td align="center"> &quot;$1&quot; &quot;$ 2&quot; … &quot;$n &quot;</td><td align="center"> &quot;$1&quot; &quot;$ 2&quot; … &quot;$n &quot;</td></tr></tbody></table><p>例如：某命令传递了 5 个参数，那么对于 &quot;$*&quot; 来说，这 5 个参数会合并到一起形成 1 个数据，这一个数据包含了 5 个参数，它们之间是 <strong>无法分割</strong> 的；而对于 &quot;$@&quot; 来说，这 5 个参数是<strong>相互独立</strong>的，它们是 5 个数据。</p><h4 id="_1-3-预定义变量" tabindex="-1">1.3 预定义变量 <a class="header-anchor" href="#_1-3-预定义变量" aria-label="Permalink to &quot;1.3 预定义变量&quot;">​</a></h4><p>预定义变量是在 Shell 一开始时就定义的变量，这一点和默认环境变量有些类似。不同的是，<strong>预定义变量不能重新定义</strong>，用户只能根据 Shell 的定义来使用这些变量。严格来说，位置参数变量也是预定义变量的一种，只是位置参数变量的作用比较统一，所以一般把位置参数变量单独划分为一类变量。</p><table><tbody><tr><td align="center" width="100px">$?</td><td align="left"> 最后一次执行的命令的返回状态。如果这个变量的值为 0，则证明上一条命令正确执行；如果这个变量的值为非 0 (具体是哪个数由命令自己来决定)，则证明上一条命令执行错误。</td></tr><tr><td align="center" width="100px">$$</td><td align="left"> 代表当前进程的进程号(PID)。</td></tr><tr><td align="center" width="100px">$!</td><td align="left"> 代表后台运行的最后一个进程的进程号(PID)。</td></tr></tbody></table><h4 id="_1-4-环境变量" tabindex="-1">1.4 环境变量 <a class="header-anchor" href="#_1-4-环境变量" aria-label="Permalink to &quot;1.4 环境变量&quot;">​</a></h4><p>环境变量也称为全局变量，可以在创建它们的 Shell 及其派生出来的任意子进程 Shell 中使用，环境变量又可以分为自定义环境变量和 bash 内置的环境变量。</p><p>环境变量可以在命令行中设置和创建，用户退出命令行时这些变量值就会丢失，那如何永久保存环境变量呢？可以在用户家目录下的 .bash_profile(或者是.profile) 或 .bashrc(非用户登录模式特有，如：SSH) 文件中，这两个文件设置后是针对特定用户的，也可以在 /etc/profile 文件中定义环境变量，该文件设置后将会影响所有的用户，就是说在这三个文件中进行定义的环境变量在用户登录后就会进行初始化。</p><ul><li>常见环境变量</li></ul><table><tbody><tr><td align="center"> HOME </td><td align="left">/etc/passwd 文件中列出的用户主目录 </td></tr><tr><td align="center"> PATH </td><td align="left"> 系统默认的可执行文件搜索路径 </td></tr><tr><td align="center"> HISTSIZE </td><td align="left"> 保留历史命令的数目上限 </td></tr><tr><td align="center"> OSTYPE </td><td align="left"> 系统类型 </td></tr><tr><td align="center"> PWD </td><td align="left"> 当前工作目录 </td></tr><tr><td align="center"> TERM </td><td align="left"> 终端类型，常用的有 vt100, ansi, vt200, xterm 等 </td></tr><tr><td align="center"> PS1, PS2 </td><td align="left"> 默认提示符($)及换行提示符(&gt;) </td></tr><tr><td align="center"> IFS </td><td align="left"> Internal Field Separator, 默认为空格，tab 及换行符 </td></tr></tbody></table>`,51)])])}const c=a(e,[["render",l]]);export{u as __pageData,c as default};
